import { useMutation } from '@tanstack/react-query';
import { TxSearchDTO, TxSearchResponseDTO } from '~/entities/exchange/api/dtos/types';
import { exchangeApi } from '~/entities/exchange/api/exchange-api';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';

export const useTxSearchMutation = (options?: MutationOptions<TxSearchDTO, CBDCAxiosError, TxSearchResponseDTO>) => {
  const mutation = useMutation<TxSearchResponseDTO, CBDCAxiosError, TxSearchDTO>({
    ...options,
    mutationFn: exchangeApi.txSearch,
    onSuccess: (data) => {
      // 바우처에서 이유는 모르겠지만 placeNm에 값을 넣지 않고 placeSecret 값을 넣는 경우가 있음.
      // 이 경우 placeNm에 값을 넣어줌.
      if (!data?.placeNm && data.placeSecret) {
        data.placeNm = data.placeSecret;
      }
      return data;
    },
  });

  return {
    ...mutation,
  };
};
